import math, logging, multiprocessing, traceback, queuelogger

def coordinate_descent(adj_params, params, error_func):
    params = dict(params)
    dp = {param_name: 1.0 for param_name in adj_params}
    best_err = error_func(params)
    logging.info("Coordinate descent initial error: %s", best_err)
    threshold = 1e-05
    rounds = 0
    while True:
        if sum(dp.values()) > threshold and rounds < 10000:
            rounds += 1
            for param_name in adj_params:
                orig = params[param_name]
                params[param_name] = orig + dp[param_name]
                err = error_func(params)
                if err < best_err:
                    best_err = err
                    dp[param_name] *= 1.1
                else:
                    params[param_name] = orig - dp[param_name]
                    err = error_func(params)
                    if err < best_err:
                        best_err = err
                        dp[param_name] *= 1.1
                    else:
                        params[param_name] = orig
                        dp[param_name] *= 0.9

    logging.info("Coordinate descent best_err: %s  rounds: %d", best_err, rounds)
    return params


def background_coordinate_descent(printer, adj_params, params, error_func):
    (parent_conn, child_conn) = multiprocessing.Pipe()

    def wrapper():
        queuelogger.clear_bg_logging()
        try:
            res = coordinate_descent(adj_params, params, error_func)
        except:
            child_conn.send((True, traceback.format_exc()))
            child_conn.close()
            return None
        else:
            child_conn.send((False, res))
            child_conn.close()

    calc_proc = multiprocessing.Process(target=wrapper)
    calc_proc.daemon = True
    calc_proc.start()
    reactor = printer.get_reactor()
    gcode = printer.lookup_object("gcode")
    eventtime = last_report_time = reactor.monotonic()
    while calc_proc.is_alive():
        if eventtime > last_report_time + 5.0:
            last_report_time = eventtime
            gcode.respond_info("Working on calibration...", log=False)
        eventtime = reactor.pause(eventtime + 0.1)

    (is_err, res) = parent_conn.recv()
    if is_err:
        raise Exception("Error in coordinate descent: %s" % (res,))
    calc_proc.join()
    parent_conn.close()
    return res


def trilateration(sphere_coords, radius2):
    (sphere_coord1, sphere_coord2, sphere_coord3) = sphere_coords
    s21 = matrix_sub(sphere_coord2, sphere_coord1)
    s31 = matrix_sub(sphere_coord3, sphere_coord1)
    d = math.sqrt(matrix_magsq(s21))
    ex = matrix_mul(s21, 1.0 / d)
    i = matrix_dot(ex, s31)
    vect_ey = matrix_sub(s31, matrix_mul(ex, i))
    ey = matrix_mul(vect_ey, 1.0 / math.sqrt(matrix_magsq(vect_ey)))
    ez = matrix_cross(ex, ey)
    j = matrix_dot(ey, s31)
    x = (radius2[0] - radius2[1] + d ** 2) / (2.0 * d)
    y = (radius2[0] - radius2[2] - x ** 2 + (x - i) ** 2 + j ** 2) / (2.0 * j)
    z = -math.sqrt(radius2[0] - x ** 2 - y ** 2)
    ex_x = matrix_mul(ex, x)
    ey_y = matrix_mul(ey, y)
    ez_z = matrix_mul(ez, z)
    return matrix_add(sphere_coord1, matrix_add(ex_x, matrix_add(ey_y, ez_z)))


def matrix_cross(m1, m2):
    return [
     m1[1] * m2[2] - m1[2] * m2[1],
     m1[2] * m2[0] - m1[0] * m2[2],
     m1[0] * m2[1] - m1[1] * m2[0]]


def matrix_dot(m1, m2):
    return m1[0] * m2[0] + m1[1] * m2[1] + m1[2] * m2[2]


def matrix_magsq(m1):
    return m1[0] ** 2 + m1[1] ** 2 + m1[2] ** 2


def matrix_add(m1, m2):
    return [
     m1[0] + m2[0], m1[1] + m2[1], m1[2] + m2[2]]


def matrix_sub(m1, m2):
    return [
     m1[0] - m2[0], m1[1] - m2[1], m1[2] - m2[2]]


def matrix_mul(m1, s):
    return [
     m1[0] * s, m1[1] * s, m1[2] * s]

